// The DEDALO logo and mark, as the build embeds them from build/brand/ — written by
// build/brand.mjs, run it again when a file there changes. The logo carries the name and goes
// on the cover; the mark is the D alone and goes in the running header. Kept as a module
// rather than an asset so that Node, which has no canvas and no fetch of a local file, can put
// them into the Word file as well as the sheet — and Word shows no WebP, so each travels once
// more as a PNG, as bare base64.
export const DEDALO_LOGO = 'data:image/webp;base64,';
export const DEDALO_LOGO_SIZE = { width: 360, height: 275 };
export const DEDALO_MARK = 'data:image/webp;base64,';
export const DEDALO_MARK_SIZE = { width: 160, height: 155 };
export const DEDALO_LOGO_PNG = '';
export const DEDALO_LOGO_PNG_SIZE = { width: 240, height: 183 };
export const DEDALO_MARK_PNG = '';
export const DEDALO_MARK_PNG_SIZE = { width: 96, height: 93 };
